        "title": "<ruby>練習<rt>れんしゅう</rt></ruby>C - Mẫu 2: Truyền đạt lại lời nhắn điện thoại (～と <ruby>言<rt>い</rt></ruby>って いました)",
        "context": "Nhắn lại lời của khách hàng hoặc đồng nghiệp.",
