            "id": "rc33-3-l3",
            "speaker": "A",
            "jp": "じゃ、「<u>あしたの パーティーに <ruby>行<rt>い</rt></ruby>けない</u>」と <ruby>伝<rt>つた</rt></ruby>えて いただけませんか。",
